const $=id=>document.getElementById(id);
const steps=[
 {letter:'B',title:'Baseline the text',sub:'Translation & structure',anchor:'Before you build your view, compare the translations to see the blueprint anew.',prompts:['Read the complete paragraph in NASB 1995. Where do its sentences begin and end?','Mark repeated words, contrasts, conditions, and purpose statements. What connects the thoughts?','If another translation differs, note the wording before deciding what the difference means.']},
 {letter:'R',title:'Read the surrounding',sub:'Literary context & flow',anchor:'A verse pulled out of its natural place becomes a pretext for human grace.',prompts:['Read the paragraphs immediately before and after. How does your passage move the author’s thought forward?','What kind of writing is this: a story, poem, letter, prophecy, or something else?','How does the passage contribute to the message of the book?']},
 {letter:'I',title:'Investigate the past',sub:'Historical setting & occasion',anchor:'To hear what God is saying to you, first hear what was heard by the first-century few.',prompts:['Who wrote this book, and who first heard it? Note what is known and what remains uncertain.','What situation, question, or conflict helps explain the passage?','What does the text itself reveal about its audience? Distinguish evidence from a possible reconstruction.']},
 {letter:'D',title:'Dig into details',sub:'Key words & grammar',anchor:'Small words hold big weight; unpack the grammar to unlock the gate.',prompts:['Choose two to four words that carry the passage’s meaning. How are they used in this context?','Notice who acts, who receives the action, and how commands and promises relate.','Check a reliable language resource before assigning a Greek or Hebrew meaning. Record your source.']},
 {letter:'G',title:'Grasp the core idea',sub:'Authorial intent & big idea',anchor:'If you cannot state the author’s aim in a sentence, you do not yet understand his message.',prompts:['Write one memorable sentence explaining the author’s central message to the original audience.','Which details in the paragraph support your sentence?','Does your summary include the whole paragraph, or only your favorite verse?']},
 {letter:'E',title:'Equip for today',sub:'Meaningful application',anchor:'Truth is not truly learned until it is lived.',prompts:['What timeless truth connects the original situation with your life today?','What would it look like to practice that truth this week? What common misreading should you avoid?','What challenged your assumptions in this passage?','How might its message change the way you treat someone?','What specific response could your group encourage one another to practice?']}
];
const levels={1:{name:'New reader',help:'Simple questions and everyday explanations.',extra:'Take your time. Use your own words, and write down anything you want to ask a trusted teacher.'},2:{name:'Regular reader',help:'Clear questions with practical application.',extra:'Connect your observations to the main point. Keep interpretation grounded in the paragraph.'},3:{name:'Study leader',help:'Word studies, structure, and group discussion.',extra:'Add a structural outline and transliterated word notes from reliable resources. Prepare a follow-up question and a leader hint for your group.'},4:{name:'Advanced / ministry',help:'Syntax, lexical range, and interpretive questions.',extra:'Evaluate original-language syntax and lexical range in context. Where relevant, compare textual variants and scholarly readings; separate consensus from debated conclusions.'}};
const sampleNotes=[
 'Verses 4–5 call for joy and gentleness. Verses 6–7 connect prayer with God’s guarding peace. Verses 8–9 connect careful thought with practiced obedience.',
 'Read 4:1–3 and 4:10–13 alongside this paragraph. Notice how these instructions sit among appeals for unity and the discussion of contentment.',
 'This letter addresses a Christian community. Use the book’s opening and its references to imprisonment to investigate the writer’s situation; avoid reconstructing more than the evidence supports.',
 'Notice the contrast in verse 6, the promise in verse 7, and the paired instructions to dwell and practice in verses 8–9. The paragraph links attention, action, and trust.',
 'Believers are called to joyful, prayerful, thoughtful obedience in the Lord, sustained by God’s peace.',
 'Bring concerns to God with gratitude and practice what is good. This passage should not become a reason to shame someone struggling with anxiety. Which concern could you bring to prayer? What deserves your attention? What good practice could you begin this week?'
];
let current=null,active=0,toastTimer;
let library=[];let storageAvailable=true;try{const v=JSON.parse(localStorage.getItem('bridge-notebook-v1')||'[]');if(Array.isArray(v))library=v.filter(x=>x&&typeof x.passage==='string'&&levels[x.level]&&Array.isArray(x.notes)&&Array.isArray(x.done)).map(x=>({...x,notes:Array.from({length:6},(_,i)=>typeof x.notes[i]==='string'?x.notes[i]:''),done:Array.from({length:6},(_,i)=>!!x.done[i])}));}catch{storageAvailable=false;}
function toast(t){$('toast').textContent=t;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3500);}
function readingUrl(p){return 'https://www.biblegateway.com/passage/?search='+encodeURIComponent(p)+'&version=NASB1995';}
function validPassage(p){return /^(?:[1-3]\s*)?[A-Za-z][A-Za-z\s.]+\s+\d{1,3}:\d{1,3}(?:\s*[-–—]\s*\d{1,3})?$/.test(p);}
function openStudy(p,l,isSample=false,saved=null){current=saved?JSON.parse(JSON.stringify(saved)):{id:crypto.randomUUID(),passage:p,level:Number(l),notes:Array(6).fill(''),done:Array(6).fill(false),sample:isSample};active=0;$('passage').value=current.passage;$('level').value=current.level;$('level-help').textContent=levels[current.level].help;$('study-title').textContent=current.passage;$('study-level').textContent='Level '+current.level+' · '+levels[current.level].name;$('study-kind').textContent=current.sample?'GUIDED WORKSHEET + SAMPLE STUDY':'GUIDED WORKSHEET';$('read-link').href=readingUrl(current.passage);$('study').classList.remove('hidden');render();$('study').scrollIntoView({behavior:'smooth'});}
function render(){const s=steps[active];$('steps').replaceChildren();steps.forEach((step,i)=>{const b=document.createElement('button');b.type='button';b.className=i===active?'active':'';b.setAttribute('aria-current',i===active?'step':'false');const letter=document.createElement('b');letter.textContent=step.letter;const title=document.createElement('span');title.textContent=step.title;const check=document.createElement('small');check.textContent=current.done[i]?'✓':'';b.append(letter,title,check);b.onclick=()=>{active=i;render();};$('steps').append(b);});
 const panel=$('step-panel');panel.innerHTML='<div class="eyebrow" id="step-sub"></div><h3 id="step-title"></h3><blockquote id="step-anchor"></blockquote><ul id="prompt-list"></ul><p class="muted" id="tier-tip"></p><div id="example"></div><label for="notes">Your observations & reflections</label><textarea id="notes" placeholder="Write what you notice, what it means, and what you will do…"></textarea><label class="done"><input type="checkbox" id="complete"> I’ve worked through this step</label><div class="step-bottom"><button class="outline" id="previous">← Previous</button><button class="outline" id="next">Next step →</button></div>';
 $('step-sub').textContent='STEP '+(active+1)+' OF 6 · '+s.sub.toUpperCase();$('step-title').textContent=s.letter+' — '+s.title;$('step-anchor').textContent=s.anchor;
 s.prompts.forEach(p=>{const li=document.createElement('li');li.textContent=p;$('prompt-list').append(li);});$('tier-tip').textContent=levels[current.level].extra;
 if(current.sample){const d=document.createElement('details'),sm=document.createElement('summary'),p=document.createElement('p'),a=document.createElement('a');sm.textContent='Explore the sample observation';p.textContent=sampleNotes[active];a.textContent='Read the source passage ↗';a.href=readingUrl('Philippians 4:4-9');a.target='_blank';a.rel='noopener noreferrer';d.append(sm,p,a);$('example').append(d);}
 $('notes').value=current.notes[active];$('notes').oninput=e=>{current.notes[active]=e.target.value;};$('complete').checked=current.done[active];$('complete').onchange=e=>{current.done[active]=e.target.checked;render();};$('previous').disabled=active===0;$('previous').onclick=()=>{active--;render();};$('next').textContent=active===5?'Save study ✓':'Next step →';$('next').onclick=()=>{if(active===5)save();else{active++;render();}};const n=current.done.filter(Boolean).length;$('progress-label').textContent=n+' of 6 steps completed';$('progress-fill').style.width=(n/6*100)+'%';}
function persist(){try{localStorage.setItem('bridge-notebook-v1',JSON.stringify(library));storageAvailable=true;return true;}catch{storageAvailable=false;toast('Browser storage is unavailable or full. Download your notes to keep them.');return false;}}
function save(){if(!current)return;current.updated=new Date().toISOString();const i=library.findIndex(s=>s.id===current.id);const copy=JSON.parse(JSON.stringify(current));if(i<0)library.unshift(copy);else library[i]=copy;if(persist())toast('Study saved in this browser.');$('count').textContent=library.length;}
function notebook(){const list=$('library-list');list.replaceChildren();if(!library.length){const p=document.createElement('p');p.textContent='Your first study is waiting. Open a passage, add your notes, then select Save study.';list.append(p);}library.forEach(s=>{const row=document.createElement('div');row.className='saved-row';const left=document.createElement('div'),title=document.createElement('strong'),sub=document.createElement('small'),right=document.createElement('div'),open=document.createElement('button'),del=document.createElement('button');title.textContent=s.passage;sub.textContent='Level '+s.level+' · '+s.done.filter(Boolean).length+'/6 completed';left.append(title,sub);open.textContent='Open';open.className='outline';open.onclick=()=>{$('library').close();openStudy(s.passage,s.level,s.sample,s);};del.textContent='Delete';del.className='text-button';del.setAttribute('aria-label','Delete saved study '+s.passage);del.onclick=()=>{if(confirm('Delete the saved study for '+s.passage+'?')){library=library.filter(x=>x.id!==s.id);persist();$('count').textContent=library.length;notebook();}};right.append(open,del);row.append(left,right);list.append(row);});if(!$('library').open)$('library').showModal();}
function notesText(){return ['B.R.I.D.G.E. BIBLE GUIDE',current.passage,'Level '+current.level+' · '+levels[current.level].name,readingUrl(current.passage),'',...steps.flatMap((s,i)=>[s.letter+' — '+s.title,current.notes[i]||'(No notes yet)',''])].join('\n');}
function shareUrl(){const u=new URL(location.href);u.hash='workspace';u.search='';u.searchParams.set('passage',current.passage);u.searchParams.set('level',current.level);return u.href;}
async function share(){try{await navigator.clipboard.writeText(shareUrl());toast('Passage link copied. Personal notes are not included.');}catch{prompt('Copy this passage link (personal notes are not included):',shareUrl());}}
function printAll(){const original=$('step-panel').innerHTML;const panel=$('step-panel');panel.replaceChildren();steps.forEach((s,i)=>{const section=document.createElement('section'),h=document.createElement('h3'),p=document.createElement('p');h.textContent=s.letter+' — '+s.title;p.textContent=current.notes[i]||'(No notes yet)';p.style.whiteSpace='pre-wrap';section.style.breakInside='avoid';section.append(h,p);panel.append(section);});window.print();render();}
 $('start-form').onsubmit=e=>{e.preventDefault();const p=$('passage').value.trim();if(!validPassage(p)){$('form-error').textContent='Enter one passage with verses, such as John 15:1–8. For a whole chapter, begin by choosing its first complete paragraph.';return;}$('form-error').textContent='';openStudy(p,$('level').value,/^Philippians\s+4:4\s*[-–—]\s*9$/i.test(p));};$('level').onchange=()=>{$('level-help').textContent=levels[$('level').value].help;};$('sample').onclick=()=>{openStudy('Philippians 4:4–9',$('level').value,true);};$('save').onclick=save;$('notebook').onclick=notebook;$('close-library').onclick=()=>{$('library').close();};$('share').onclick=share;$('print').onclick=printAll;$('export').onclick=()=>{const blob=new Blob([notesText()],{type:'text/plain;charset=utf-8'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='BRIDGE-'+current.passage.replace(/[^a-z0-9]/gi,'-')+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Notes downloaded.');};$('count').textContent=library.length;
 const params=new URLSearchParams(location.search);const initial=params.get('passage');if(initial&&validPassage(initial)){const l=Number(params.get('level'))||2;openStudy(initial,levels[l]?l:2,/^Philippians\s+4:4\s*[-–—]\s*9$/i.test(initial));}
 window.addEventListener('beforeunload',e=>{if(!current)return;const saved=library.find(x=>x.id===current.id);if(current.notes.some(Boolean)&&(!saved||JSON.stringify(saved.notes)!==JSON.stringify(current.notes))){e.preventDefault();e.returnValue='';}});
